-- Ashenvale: creature abilities
-- Most of the zone's creatures (Foulweald and Thistlefur furbolgs, Xavian and Felmusk satyrs, the Wrathtail naga, the Warsong and
-- Splintertree orcs, the Forest Song draenei, the Emeraldon dragonkin, the wildlife) had no AI or ran classic rows. Ashenvale is the
-- Cataclysm revamp, so port their abilities from the Cataclysm data, and from the classic data where Cataclysm has none, keeping
-- the quest scripts already in place. Sentinel Farsong and Illiyana Moonblaze drop their classic archer template for the Cataclysm
-- rows. The creatures no reference scripts (Ashenvale Bowmen, Brutusk, the guards) cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '3691,3696,3713,3717,3730,3733,3734,3735,3736,3743,3745,3750,3752,3754,3755,3757,3758,3762,3763,3765,3767,3770,3771,3772,3773,3774,3780,3783,3797,3799,3803,3809,3810,3812,3815,3817,3821,3823,3825,3845,3846,3847,3892,3917,3921,3922,3924,3925,3926,3932,3940,3941,3942,3943,3944,3987,4273,4619,5314,6072,6073,6087,6115,8015,10559,10639,10640,10641,10642,11697,12037,12474,12475,12476,12759,12859,12903,12940,14733,14753,17300,25863,25924,25951,26116,32850,33187,33193,33204,33276,33356,33389,33390,33419,33443,33444,33688,33777,34177,34204,34206,34208,34241,34242,34294,34295,34314,34366,34419,34420,34499,34500,34590,34591,34592,39254,43653,43657';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '33195,34007,51507,51770,51814,51816,51867';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
